function ProductCard({ product }: { product: Product }) {
  // rendered during SSR and on the client
  const postedAgo = Math.round(
    (Date.now() - product.createdAt) / 60000,
  );
  const price = product.price.toLocaleString(undefined, {
    style: 'currency',
    currency: product.currency,
  });

  return (
    <article>
      <h3>{product.name}</h3>
      <span>{price}</span>
      <time dateTime={new Date(product.createdAt).toISOString()}>
        {postedAgo} min ago
      </time>
    </article>
  );
}
